"""Smart Health Consulting - main Streamlit application.

Run with:  streamlit run app.py
"""

from pathlib import Path

import streamlit as st
from dotenv import load_dotenv

load_dotenv()

import auth  # noqa: E402  (imported after load_dotenv on purpose)
import database  # noqa: E402
import health_consultation as hc  # noqa: E402

BASE_DIR = Path(__file__).resolve().parent
PAGES = ["Home", "Health Consultation", "History", "About"]

DISCLAIMER = (
    "<strong>Medical disclaimer:</strong> This application provides general, educational "
    "information generated by AI. It does not diagnose any condition and is not a "
    "substitute for professional medical advice, diagnosis or treatment. Always "
    "consult a qualified healthcare professional. In an emergency, contact your "
    "local emergency number immediately."
)

st.set_page_config(
    page_title="Smart Health Consulting",
    page_icon="🩺",
    layout="wide",
    initial_sidebar_state="expanded",
)


# ---------------------------------------------------------------- helpers
def load_css() -> None:
    css_file = BASE_DIR / "assets" / "style.css"
    if css_file.exists():
        st.markdown(f"<style>{css_file.read_text(encoding='utf-8')}</style>", unsafe_allow_html=True)


def show_disclaimer() -> None:
    st.markdown(f'<div class="disclaimer">{DISCLAIMER}</div>', unsafe_allow_html=True)


def card(title: str, text: str) -> None:
    # Only static, developer-written text is passed here (never user input).
    st.markdown(
        f'<div class="card"><h4>{title}</h4><p>{text}</p></div>',
        unsafe_allow_html=True,
    )


def format_date(value: str) -> str:
    return f"{value} UTC"


# ------------------------------------------------------- login / register
def render_auth_forms() -> None:
    st.subheader("Please log in to continue")
    login_tab, register_tab = st.tabs(["Login", "Register"])

    with login_tab:
        with st.form("login_form"):
            username = st.text_input("Username")
            password = st.text_input("Password", type="password")
            submitted = st.form_submit_button("Log in")
        if submitted:
            ok, message = auth.login_user(username, password)
            if ok:
                st.rerun()
            else:
                st.error(message)

    with register_tab:
        with st.form("register_form"):
            new_username = st.text_input("Choose a username", help="3-30 letters, numbers or underscores")
            email = st.text_input("Email")
            new_password = st.text_input("Password", type="password", help="At least 8 characters, with a letter and a number")
            confirm = st.text_input("Confirm password", type="password")
            submitted = st.form_submit_button("Create account")
        if submitted:
            ok, message = auth.register_user(new_username, email, new_password, confirm)
            if ok:
                st.success(message)
            else:
                st.error(message)


# ------------------------------------------------------------------ pages
def page_home() -> None:
    st.markdown(
        """
        <div class="hero">
            <h1>🩺 Smart Health Consulting</h1>
            <p>Describe your symptoms and receive clear, general health information
            and self-care guidance powered by AI - for learning and awareness only.</p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    col1, col2, col3 = st.columns(3)
    with col1:
        card("🤖 AI Health Guidance", "Enter symptoms and get general information, possible explanations and self-care tips.")
    with col2:
        card("🗂️ Consultation History", "Every consultation is saved privately to your account so you can review or delete it.")
    with col3:
        card("🔒 Secure Accounts", "Passwords are hashed with bcrypt and your records are visible only to you.")

    st.write("")
    if auth.is_logged_in():
        st.success(f"You are logged in as **{auth.current_username()}**. Open *Health Consultation* in the sidebar to begin.")
    else:
        st.info("Use the *Health Consultation* page in the sidebar to log in or create a free account.")
    show_disclaimer()


def page_consultation() -> None:
    st.title("Health Consultation")
    if not auth.is_logged_in():
        render_auth_forms()
        return

    show_disclaimer()
    with st.form("consultation_form"):
        symptoms = st.text_area(
            "Describe your symptoms",
            height=160,
            max_chars=hc.MAX_SYMPTOM_CHARS,
            placeholder="Example: I have had a mild headache and a sore throat since yesterday...",
        )
        col1, col2 = st.columns(2)
        age_group = col1.selectbox("Age group (optional)", hc.AGE_GROUPS)
        duration = col2.selectbox("Symptom duration (optional)", hc.DURATIONS)
        submitted = st.form_submit_button("Get health guidance")

    if submitted:
        error = hc.validate_symptoms(symptoms)
        if error:
            st.warning(error)
        else:
            with st.spinner("Generating guidance... this can take a few seconds."):
                ok, result = hc.get_health_guidance(symptoms, age_group, duration)
            if ok:
                database.add_consultation(
                    auth.current_user_id(), symptoms.strip(), result, age_group, duration
                )
                st.session_state["last_result"] = result
            else:
                st.session_state.pop("last_result", None)
                st.error(result)

    if "last_result" in st.session_state:
        st.subheader("AI-generated guidance")
        with st.container(border=True):
            st.markdown(st.session_state["last_result"])
        st.caption("Saved to your History. This is general information, not a diagnosis.")


def page_history() -> None:
    st.title("Consultation History")
    if not auth.is_logged_in():
        render_auth_forms()
        return

    user_id = auth.current_user_id()
    rows = database.list_consultations(user_id)  # filtered by user_id in SQL
    if not rows:
        st.info("You have no saved consultations yet.")
        return

    df = database.consultations_dataframe(user_id)
    st.caption(f"{len(df)} saved consultation(s)")

    summary = df[["id", "created_at", "age_group", "duration", "symptoms"]].copy()
    summary["symptoms"] = summary["symptoms"].str.slice(0, 80)
    summary.columns = ["ID", "Date (UTC)", "Age group", "Duration", "Symptoms (preview)"]
    st.dataframe(summary, use_container_width=True, hide_index=True)

    st.download_button(
        "Download my history (CSV)",
        data=df.to_csv(index=False).encode("utf-8"),
        file_name="my_consultations.csv",
        mime="text/csv",
    )

    st.divider()
    st.subheader("View a record")
    options = {f"#{r['id']} - {r['created_at']}": r["id"] for r in rows}
    choice = st.selectbox("Select a consultation", list(options.keys()))
    # Re-fetch with the user-level access check (never trust the UI alone).
    record = database.get_consultation(user_id, options[choice])
    if record is None:
        st.error("Record not found.")
        return

    st.markdown(f"**Date:** {format_date(record['created_at'])}")
    st.markdown(f"**Age group:** {record['age_group'] or 'Not specified'}  |  **Duration:** {record['duration'] or 'Not specified'}")
    st.markdown("**Your symptoms:**")
    st.text(record["symptoms"])
    st.markdown("**AI response:**")
    with st.container(border=True):
        st.markdown(record["ai_response"])

    st.divider()
    col1, col2 = st.columns(2)
    with col1:
        if st.button("Delete this record"):
            st.session_state["confirm_delete"] = record["id"]
        if st.session_state.get("confirm_delete") == record["id"]:
            st.warning("Delete this consultation permanently?")
            if st.button("Yes, delete it"):
                database.delete_consultation(user_id, record["id"])
                st.session_state.pop("confirm_delete", None)
                st.rerun()
    with col2:
        if st.button("Delete ALL my history"):
            st.session_state["confirm_delete_all"] = True
        if st.session_state.get("confirm_delete_all"):
            st.warning("This removes every saved consultation permanently.")
            if st.button("Yes, delete everything"):
                database.delete_all_consultations(user_id)
                st.session_state.pop("confirm_delete_all", None)
                st.session_state.pop("confirm_delete", None)
                st.rerun()


def page_about() -> None:
    st.title("About")
    st.markdown(
        """
        ### Objective
        Smart Health Consulting is a portfolio project that shows how to combine a
        Python web interface, a database, secure authentication and a large language
        model to deliver general health information.

        ### Features
        - User registration, login and logout with bcrypt-hashed passwords
        - AI-generated general information, possible explanations, self-care guidance
          and advice on when to seek professional help
        - Private consultation history stored in SQLite, with view, delete and CSV export
        - Healthcare-themed, responsive interface

        ### Technology stack
        Python, Streamlit, OpenAI-compatible API (OpenAI or Groq), SQLite, Pandas, bcrypt, python-dotenv

        ### Limitations
        - AI output can be incomplete, outdated or wrong.
        - The app cannot examine you, order tests or know your medical history.
        - It does not diagnose, prescribe or handle emergencies.
        - Symptom text is sent to the selected AI provider (OpenAI or Groq) to generate a response; do not enter names or other identifying details.
        """
    )
    show_disclaimer()


# ------------------------------------------------------------------- main
def main() -> None:
    database.init_db()
    load_css()

    with st.sidebar:
        st.markdown("## 🩺 Smart Health")
        page = st.radio("Navigation", PAGES, label_visibility="collapsed")
        st.divider()
        if auth.is_logged_in():
            st.write(f"Signed in as **{auth.current_username()}**")
            if st.button("Log out"):
                auth.logout()
                st.rerun()
        else:
            st.caption("You are not logged in.")
        st.caption("Educational use only. Not medical advice.")

    if page == "Home":
        page_home()
    elif page == "Health Consultation":
        page_consultation()
    elif page == "History":
        page_history()
    else:
        page_about()


main()
